ALTER TABLE public.public_audio_broadcasts ADD COLUMN last_seen timestamptz NOT NULL DEFAULT now();
CREATE OR REPLACE FUNCTION public.join_public_audio(p_broadcast uuid, p_hash text, p_language text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE sid uuid; BEGIN PERFORM id FROM public_audio_broadcasts WHERE id=p_broadcast AND ended_at IS NULL AND expires_at>now() AND last_seen>now()-interval '20 seconds' FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Broadcast ended'; END IF; IF (SELECT count(*) FROM public_audio_listeners WHERE broadcast_id=p_broadcast AND last_seen>now()-interval '20 seconds')>=5 OR (SELECT count(*) FROM public_audio_listeners WHERE broadcast_id=p_broadcast)>=100 THEN RAISE EXCEPTION 'Broadcast full'; END IF; INSERT INTO public_audio_listeners(broadcast_id,token_hash,language) VALUES(p_broadcast,p_hash,p_language) RETURNING id INTO sid; RETURN sid; END $$;
REVOKE ALL ON FUNCTION public.join_public_audio(uuid,text,text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.join_public_audio(uuid,text,text) TO service_role;